import React from "react";
import {Html5Audio, Sequence, staticFile, useVideoConfig} from "remotion";

/**
 * The bundled CC0 sound-effect pack (public/sfx/, generated by the kit, no
 * third-party audio). Each entry mirrors the front matter of its card in docs/shots/sfx/<id>.md
 * (file, seconds, gain, use); `bun run check` fails when they disagree. Every file is already normalised to about −20 LUFS
 * (`sfxTargetLUFS`), so every gain is 1.0; change a gain only after listening.
 */
export type SfxId = "whoosh" | "pop" | "tick" | "boom" | "ding" | "riser" | "glitch" | "drop";

export const SFX: Record<SfxId, {src: string; seconds: number; gain: number; use: string}> = {
  whoosh: {src: "sfx/whoosh.mp3", seconds: 0.85, gain: 1, use: "the camera or the story jumps to a new place or time"},
  pop: {src: "sfx/pop.mp3", seconds: 0.23, gain: 1, use: "a number, label or chip appears on screen"},
  tick: {src: "sfx/tick.mp3", seconds: 0.11, gain: 1, use: "counting up or down on screen (days, years, items)"},
  boom: {src: "sfx/boom.mp3", seconds: 1.65, gain: 1, use: "the turn: the fact that flips the story"},
  ding: {src: "sfx/ding.mp3", seconds: 1.65, gain: 1, use: "the answer lands, the payoff"},
  riser: {src: "sfx/riser.mp3", seconds: 2.05, gain: 1, use: "the half second before a reveal"},
  glitch: {src: "sfx/glitch.mp3", seconds: 0.65, gain: 1, use: "something is wrong: a myth, a broken record, a map error"},
  drop: {src: "sfx/drop.mp3", seconds: 0.5, gain: 1, use: "a plan fails, a hope is refused"},
};

/**
 * Base level for every effect, multiplied by the file's gain. 0.7 ≈ −3 dB under
 * the voice, chosen by listening: level with the voice pulls the video toward
 * a meme video.
 */
export const SFX_VOLUME = 0.7;

/**
 * A cue: a bundled effect by `id`, or your own file under public/ by `src`.
 * `at` is an absolute frame; get it from `frameAtWord`, never type it by hand.
 */
export type SfxCue = {at: number; id?: SfxId; src?: string; volume?: number};

/**
 * Sound effects as accents (§8): at most `sfxMaxPerVideo` per video. Render
 * at the composition root (ShortsTemplate does), not inside a scene Sequence,
 * so an effect on a scene boundary is not cut off.
 */
export const Sfx: React.FC<{cues: readonly SfxCue[]}> = ({cues}) => {
  const {fps} = useVideoConfig();
  return (
    <>
      {cues.map((c, i) => {
        const entry = c.id ? SFX[c.id] : undefined;
        const src = entry?.src ?? c.src;
        if (!src) throw new Error(`Sfx cue #${i + 1} at frame ${c.at} has neither id nor src.`);
        return (
          <Sequence
            key={`${src}-${c.at}-${i}`}
            from={Math.max(0, Math.round(c.at))}
            durationInFrames={entry ? Math.ceil(entry.seconds * fps) : undefined}
            name={`sfx ${c.id ?? src}`}
          >
            <Html5Audio src={staticFile(src)} volume={SFX_VOLUME * (entry?.gain ?? 1) * (c.volume ?? 1)} />
          </Sequence>
        );
      })}
    </>
  );
};
